import 'life_event.dart';
abstract class LifeEventRepository { Future<List<LifeEvent>> list(String profileId,{LifeEventCategory? category}); Future<LifeEvent> create(String profileId,LifeEventInput input); Future<LifeEvent> update(String profileId,String id,LifeEventInput input); Future<void> delete(String profileId,String id); }
class UnavailableLifeEventRepository implements LifeEventRepository { const UnavailableLifeEventRepository(); Future<T> _fail<T>()=>Future.error(StateError('Life Events unavailable.')); @override Future<LifeEvent> create(String p,LifeEventInput i)=>_fail(); @override Future<void> delete(String p,String i)=>_fail(); @override Future<List<LifeEvent>> list(String p,{LifeEventCategory? category})=>_fail(); @override Future<LifeEvent> update(String p,String i,LifeEventInput v)=>_fail(); }
